'use strict';

// MODULES //

var isScalarMostlySafeCompatible = require( '@stdlib/ndarray/base/assert/is-scalar-mostly-safe-compatible' ); // eslint-disable-line id-length
var empty = require( '@stdlib/ndarray/base/empty' );
var broadcastScalar = require( '@stdlib/ndarray/base/broadcast-scalar' );
var assign = require( '@stdlib/ndarray/base/assign' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Creates an ndarray having a specified shape, data type, and filled with a specified value.
*
* @param {*} value - fill value
* @param {*} dtype - data type
* @param {NonNegativeIntegerArray} shape - array shape
* @param {string} order - array order
* @throws {TypeError} second argument must be a recognized data type
* @throws {TypeError} fill value is not compatible with the specified data type
* @returns {ndarray} ndarray
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var arr = full( 10.0, 'float32', [ 2, 2 ], 'row-major' );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 2, 2 ]
*
* var dt = String( getDType( arr ) );
* // returns 'float32'
*/
function full( value, dtype, shape, order ) {
	var arr;
	var v;

	if ( !isScalarMostlySafeCompatible( value, dtype ) ) {
		throw new TypeError( format( 'invalid argument. Fill value is not compatible with the specified data type. Value: %s, Data Type: %s', value, dtype ) );
	}

	arr = empty( dtype, shape, order );

	// Broadcast the fill value to an ndarray of same shape and data type as the input ndarray:
	v = broadcastScalar( value, dtype, shape, order );

	// Assign the fill value to each element of the input ndarray:
	assign( [ v, arr ] ); // TODO: consider replacing with ndarray/base/assign-scalar in order to avoid zero-dimensional ndarray creation and subsequent broadcasting

	return arr;
}


// EXPORTS //

module.exports = full;
